/**
 * Twirp over `fetch`, with protobuf bodies
 *
 * See https://twitchtv.github.io/twirp/docs/spec_v7.html
 */

import { TwirpError } from "./errors.js";
import { version as apiTypesVersion } from "./version.js";

/** Options of a single request */
export interface CallOptions {
  /** The HTTP request timeout, in milliseconds; defaults to the client's `timeoutMs` */
  timeoutMs?: number;
  /** Aborts the request; it then rejects with the signal's reason */
  signal?: AbortSignal;
}

/** A protobuf message type, as generated by ts-proto */
export interface MessageType<T> {
  encode(message: T): { finish(): Uint8Array };
  decode(input: Uint8Array): T;
}

export interface TransportOptions {
  url: string;
  serverPathPrefix: string;
  authToken?: string | undefined;
  timeoutMs: number;
}

// The status code an intermediary (e.g. a proxy) answered with, as a Twirp code; see
// https://twitchtv.github.io/twirp/docs/errors.html#http-errors-from-intermediary-proxies
const INTERMEDIARY_CODES: Record<number, string> = {
  400: "internal",
  401: "unauthenticated",
  403: "permission_denied",
  404: "bad_route",
  429: "resource_exhausted",
  502: "unavailable",
  503: "unavailable",
  504: "unavailable",
};

export class Transport {
  readonly #url: string;
  readonly #serverPathPrefix: string;
  readonly #authToken: string | undefined;
  readonly timeoutMs: number;
  /** Cookies set by the server, sent back with every request, like a `requests.Session` */
  readonly #cookies = new Map<string, string>();

  constructor(opts: TransportOptions) {
    this.#url = opts.url;
    this.#serverPathPrefix = opts.serverPathPrefix;
    this.#authToken = opts.authToken;
    this.timeoutMs = opts.timeoutMs;
  }

  /** Call `service.method` with `request`, decoding the reply as `resType` */
  async call<Req, Res>(
    service: string,
    method: string,
    reqType: MessageType<Req>,
    resType: MessageType<Res>,
    request: Req,
    opts: CallOptions = {},
  ): Promise<Res> {
    // concatenated as the Python client does, so both reach the same routes
    const url = `${this.#url}${this.#serverPathPrefix}/${service}/${method}`;
    const headers: Record<string, string> = {
      "Content-Type": "application/protobuf",
      "x-api-version": apiTypesVersion,
    };
    if (this.#authToken) {
      headers["Authorization"] = `Bearer ${this.#authToken}`;
    }
    if (this.#cookies.size > 0) {
      headers["Cookie"] = [...this.#cookies].map(([k, v]) => `${k}=${v}`).join("; ");
    }

    const timeoutSignal = AbortSignal.timeout(opts.timeoutMs ?? this.timeoutMs);
    const signal =
      opts.signal === undefined ? timeoutSignal : AbortSignal.any([opts.signal, timeoutSignal]);

    let resp: Response;
    let body: Uint8Array;
    try {
      resp = await fetch(url, {
        method: "POST",
        headers,
        body: reqType.encode(request).finish(),
        signal,
      });
      this.#storeCookies(resp);
      body = new Uint8Array(await resp.arrayBuffer());
    } catch (e) {
      // a caller's abort rejects with its own reason; a timeout and network failures become
      // Twirp errors, as in the Python client
      if (opts.signal?.aborted) throw opts.signal.reason;
      if (timeoutSignal.aborted) {
        throw new TwirpError("deadline_exceeded", `${service}/${method} timed out`, undefined, {}, {
          cause: e,
        });
      }
      throw new TwirpError("unavailable", String(e), undefined, {}, { cause: e });
    }

    if (resp.status === 200) {
      return resType.decode(body);
    }
    throw errorOfResponse(resp, body);
  }

  #storeCookies(resp: Response): void {
    // `getSetCookie` is empty in browsers, where `fetch` handles cookies itself
    for (const c of resp.headers.getSetCookie?.() ?? []) {
      const pair = c.split(";", 1)[0]!;
      const eq = pair.indexOf("=");
      if (eq > 0) this.#cookies.set(pair.slice(0, eq).trim(), pair.slice(eq + 1).trim());
    }
  }
}

function errorOfResponse(resp: Response, body: Uint8Array): TwirpError {
  const text = new TextDecoder().decode(body);
  try {
    const err: unknown = JSON.parse(text);
    if (typeof err === "object" && err !== null && typeof (err as any).code === "string") {
      const { code, msg, meta } = err as { code: string; msg?: unknown; meta?: unknown };
      return new TwirpError(code, typeof msg === "string" ? msg : "", resp.status, stringMap(meta));
    }
  } catch {
    // not JSON: from an intermediary
  }
  const meta: Record<string, string> = {
    http_error_from_intermediary: "true",
    status_code: String(resp.status),
  };
  if (resp.status >= 300 && resp.status < 400) {
    // Twirp uses POST, which should not redirect
    const location = resp.headers.get("location");
    if (location !== null) meta["location"] = location;
    return new TwirpError(
      "internal",
      `unexpected HTTP status code ${resp.status} "${resp.statusText}" received, Location="${location}"`,
      resp.status,
      meta,
    );
  }
  meta["body"] = text;
  return new TwirpError(
    INTERMEDIARY_CODES[resp.status] ?? "unknown",
    `Error from intermediary with HTTP status code ${resp.status} "${resp.statusText}"`,
    resp.status,
    meta,
  );
}

function stringMap(x: unknown): Record<string, string> {
  if (typeof x !== "object" || x === null) return {};
  return Object.fromEntries(Object.entries(x).map(([k, v]) => [k, String(v)]));
}

/**
 * Whether `e` says the session is missing or expired
 *
 * The server reports this as a generic error; the only stable signal is the message, which
 * differs between RPCs: `open_session` says "Unknown session", others "Session not found".
 */
export function isSessionNotFound(e: unknown): boolean {
  if (!(e instanceof TwirpError)) return false;
  return (
    e.msg.includes("Session not found") ||
    e.msg.includes("Unknown session") ||
    e.msg.includes("InvalidSession")
  );
}
